import React from 'react'
import {motion} from 'framer-motion';
import { staggerContainer } from '../utils/motion.js';
import "./SectionWrapper.css";

function SectionWrapper(Component,idName) {
  return (
    function HOC(){
        return (
            <motion.section
                variants={staggerContainer()}
                initial='hidden'
                whileInView='show'
                // ::: Code Generated by Copilot 8a0c2e4f-6b7d-4f9a-8c1e-3d5b7f9d1a4e. This comment will be removed automatically after the file is saved :::
                // Sections are taller than the screen on mobile, so a 25% visibility threshold never fires and content stays hidden
                viewport={{ once: true, amount: 'some' }}
                className="AllSections"
            >
                <span className='hash-span' id={idName}>
                </span>
                <Component />
            </motion.section>
        )
    }
  )
}

export default SectionWrapper